# -*- coding: utf-8 -*-
"""Нижний блок части 2 «Правовые и репутационные риски применения ИИ»: ДЗ пары 2 и относящиеся к ней промпты."""
from lib import card, table, steps, paras, slide, sec
from prompts import PROMPTS

GROUP_ORDER_2 = ["Проверка результата"]


def s13b() -> str:
    b = slide(23, "Слайд «Итог урока 4 и домашнее задание части 2»: формулы двух частей, четыре пункта домашнего задания, «Подписал — значит проверил»",
              ["Слайд собирает весь урок 4 в одну картинку: формула части 1 (задача, необходимые данные, минимизация, обезличивание, проверка настроек, передача в ИИ) и формула части 2 (достоверность, источник, права и согласие, предвзятость и последствия, ответственность). Вместе они образуют цепочку, где решение всегда за человеком. Сфотографируйте его: это ваша шпаргалка на ближайшие недели.",
               "Если вы ещё не проходили часть 1 «Подготовка информации для работы с ИИ» — она на отдельной странице и отвечает на вопрос «что можно передать ИИ?»."],
              takeaway="Подписал — значит проверил.")
    b += card("Домашнее задание (до следующего занятия)",
              steps(["<b>Пять проверок по одному результату ИИ</b>: возьмите недавний ответ ИИ (или запустите промпт U-справка / U05 на условной теме) и пройдите достоверность, источник, права и согласие, предвзятость и последствия, ответственность. Запишите, что нашли и что исключили.",
                     "<b>Вопросы ответственному</b> по информационной безопасности или юристам предприятия: составьте 5–8 вопросов, на которые не смогли ответить (промпт U18 поможет сформулировать). Ответов на них в уроке нет намеренно: они зависят от локальных актов.",
                     "<b>Проверьте один сервис по чек-листу</b> из раздела «Авторское право и политика конфиденциальности сервиса» (промпт U21 поможет разобрать текст политики).",
                     "<b>Один файл</b> без реальных данных: результат проверки, список вопросов и вывод по сервису."])
              + '<p class="q-hint">Критерии: (1) в проверке есть хотя бы одно найденное и исключённое утверждение; (2) неизвестное записано как вопрос, а не как разрешение; (3) для сервиса указано, где хранятся данные. Необязательное задание: пройдите 15 пунктов личного чек-листа из практикума.</p>')
    b += card("Как пользоваться шаблонами промптов",
              paras(["Все шаблоны построены одинаково: <b>задача</b>, <b>для кого</b>, <b>что известно</b>, <b>что сделать</b>, <b>формат</b>, <b>границы</b>. Всё, что зависит от фактов, стоит в квадратных скобках — заполняете вы, не модель.",
                     "Перед использованием: 1) прочитайте описание промпта; 2) замените поля в скобках условными данными; 3) отправьте в разрешённый инструмент; 4) проверьте результат по пяти проверкам."]))
    items = [p for p in PROMPTS if p["group"] in GROUP_ORDER_2]
    rows = [[p["id"], p["title"], p["group"]] for p in items]
    b += table(f"Каталог: {len(items)} промптов части 2", ["№", "Название", "Группа"], rows)
    b += f'<div class="deep-bar fade"><span>⌨️ Все {len(items)} промптов части 2</span><b>Копируются целиком одной кнопкой</b></div>'
    for g in GROUP_ORDER_2:
        gitems = [p for p in PROMPTS if p["group"] == g]
        if not gitems:
            continue
        b += f'<div class="pk-grid">' + "".join(f"{{{{PK:{p['id']}}}}}" for p in gitems) + "</div>"
    b += '<p class="q-hint fade">Промпты подготовки данных и шаблонов документов — на странице части 1 «Подготовка информации для работы с ИИ». Дополнительно: восемь промптов практикума — в разделе «Практикум» выше. Все данные в промптах условные.</p>'
    b += """<div class="dl-grid fade" style="margin-top:20px">
    <a class="dl" href="../data/urok4/prompty_urok4.docx" download><span class="ico">📝</span><div><b>Промпты урока · DOCX</b><span>Все 21 промпт урока 4 + 8 промптов практикума</span></div><span class="arrow">↓</span></a>
    <a class="dl" href="../data/urok4/prompty_urok4.xlsx" download><span class="ico">📊</span><div><b>Промпты урока · XLSX</b><span>Таблица с группами и описаниями, для менеджера промптов</span></div><span class="arrow">↓</span></a>
    <a class="dl" href="../data/urok4/pamyatka_obezlichivanie_dipfeyki_kak_ne_popast.xlsx" download><span class="ico">📊</span><div><b>Excel-памятка · обезличивание, подделки и дипфейки</b><span>XLSX · 7 листов с цветовой разметкой</span></div><span class="arrow">↓</span></a>
    <a class="dl" href="../data/urok4/pamyatka_2_proverka_rezultata_ii.pdf" download><span class="ico">✅</span><div><b>Памятка 2 · Проверка результата ИИ</b><span>PDF · пять проверок, проверка факта, тест «поменяй деталь», проверка поручения</span></div><span class="arrow">↓</span></a>
    <a class="dl" href="../data/urok4/domashnee_zadanie_blank.docx" download><span class="ico">🏠</span><div><b>Домашнее задание · бланк DOCX</b><span>Пять проверок и вопросы ответственному</span></div><span class="arrow">↓</span></a>
  </div>"""
    return sec("s13", "13", "Домашнее задание и шаблоны промптов части 2",
               "Финальный блок: что сделать после части 2 и промпты для проверки результата ИИ и сервисов. Всё можно скачать.", b, "после занятия")
